import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { buildPorts } from './ports.mjs';
import { root } from './tokens.mjs';
import { poshMeasurements } from './oh-my-posh.mjs';

export function renderPoshReport(outputs = buildPorts()) {
  const lines = [
    '# Generated Oh My Posh color evidence', '',
    'Generated by `npm run accessibility:generate`; checked by `npm run accessibility`.',
    'Opaque RGB foregrounds on the explicit prompt background, including inline `|` separators.',
    'Path/primary text requires 7:1; all other text, status cues and separators require 4.5:1.',
    'Contrast failures block generation and release. Other variants are reported, not recolored.',
    'Ratios use unrounded sRGB luminance; displayed rounding does not determine a pass.', '',
    'Git precedence: diverged > modified > staged > ahead > behind > clean.',
    'Combined states retain every label/count but select one of these measured foregrounds.',
    'Status success and every nonzero exit share the same background; duration may be absent.',
    'All segments use plain style: no unmeasured powerline wedges or transparent separators.', '',
    'These are bounded prompt-color results, not whole-terminal accessibility, CVD differentiation,',
    'font legibility, terminal selection, input text, command output or screen-reader guarantees.',
    'Custom layouts, transparency, dimming and host overrides require new measurements.', '',
    '| Variant | Role/state | Foreground | Background | Ratio | Minimum | Result |',
    '|---|---|---|---|---:|---:|---|'
  ];
  for (const [file, bytes] of outputs) {
    if (!file.startsWith('oh-my-posh/')) continue;
    for (const row of poshMeasurements(JSON.parse(bytes))) {
      const pass = row.ratio >= row.minimum;
      if (file.includes('-contrast.')) assert.ok(pass, `Oh My Posh Contrast ${row.role} below floor`);
      lines.push(`| ${file.split('/')[1]} | ${row.role} | ${row.color} | ${row.background} | ${row.ratio.toFixed(3)} | ${row.minimum} | ${pass ? 'pass' : 'below floor'} |`);
    }
  }
  return `${lines.join('\n')}\n`;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const args = process.argv.slice(2);
  assert.ok(args.length === 0 || (args.length === 1 && args[0] === '--generate'),
    'Usage: node scripts/oh-my-posh-accessibility.mjs [--generate]');
  const path = resolve(root, 'docs', 'oh-my-posh-accessibility.md');
  const report = renderPoshReport();
  if (args[0] === '--generate') writeFileSync(path, report);
  else assert.equal(readFileSync(path, 'utf8'), report, 'Oh My Posh evidence drift; run npm run accessibility:generate');
}
